147	            arr.erase(arr.begin() + pos);
148	            std::cerr << "erased\n";
149	        }
150	
151	        if (fuzz_rand() % 5 == 0)
152	        {
153	            if (!arr.empty())
154	            {
155	                size_t pos = fuzz_rand() % arr.size();
156	                arr.insert(arr.begin() + pos, fuzzField(arr[pos]));
