417	void QueryFuzzer::fuzz(ASTPtr & ast)
418	{
419	    if (!ast)
420	        return;
421	
422	    // Check for exceeding max depth.
423	    ScopedIncrement depth_increment(current_ast_depth);
424	    if (current_ast_depth > 500)
425	    {
426	        // The AST is too deep (see the comment for current_ast_depth). Throw
427	        // an exception to fail fast and not use this query as an etalon, or we'll
428	        // end up in a very slow and useless loop. It also makes sense to set it
429	        // lower than the default max parse depth on the server (1000), so that
430	        // we don't get the useless error about parse depth from the server either.
431	        throw Exception(ErrorCodes::TOO_DEEP_RECURSION,
432	            "AST depth exceeded while fuzzing ({})", current_ast_depth);
433	    }
434	
435	    // Check for loops.
436	    auto [_, inserted] = debug_visited_nodes.insert(ast.get());
437	    if (!inserted)
438	    {
439	        fmt::print(stderr, "The AST node '{}' was already visited before."
440	            " Depth {}, {} visited nodes, current top AST:\n{}\n",
441	            static_cast<void *>(ast.get()), current_ast_depth,
442	            debug_visited_nodes.size(), (*debug_top_ast)->dumpTree());
443	        assert(false);
444	    }
445	
446	    // The fuzzing.
447	    if (auto * with_union = typeid_cast<ASTSelectWithUnionQuery *>(ast.get()))
448	    {
449	        fuzz(with_union->list_of_selects);
450	    }
451	    else if (auto * with_intersect_except = typeid_cast<ASTSelectIntersectExceptQuery *>(ast.get()))
452	    {
453	        auto selects = with_intersect_except->getListOfSelects();
454	        fuzz(selects);
455	    }
456	    else if (auto * tables = typeid_cast<ASTTablesInSelectQuery *>(ast.get()))
457	    {
458	        fuzz(tables->children);
459	    }
460	    else if (auto * tables_element = typeid_cast<ASTTablesInSelectQueryElement *>(ast.get()))
461	    {
462	        fuzz(tables_element->table_join);
463	        fuzz(tables_element->table_expression);
464	        fuzz(tables_element->array_join);
465	    }
466	    else if (auto * table_expr = typeid_cast<ASTTableExpression *>(ast.get()))
467	    {
468	        fuzz(table_expr->children);
469	    }
470	    else if (auto * expr_list = typeid_cast<ASTExpressionList *>(ast.get()))
471	    {
472	        fuzz(expr_list->children);
473	    }
474	    else if (auto * order_by_element = typeid_cast<ASTOrderByElement *>(ast.get()))
475	    {
476	        fuzzOrderByElement(order_by_element);
477	    }
478	    else if (auto * fn = typeid_cast<ASTFunction *>(ast.get()))
479	    {
480	        fuzzColumnLikeExpressionList(fn->arguments.get());
481	        fuzzColumnLikeExpressionList(fn->parameters.get());
482	
483	        if (fn->is_window_function && fn->window_definition)
484	        {
485	            auto & def = fn->window_definition->as<ASTWindowDefinition &>();
486	            fuzzColumnLikeExpressionList(def.partition_by.get());
487	            fuzzOrderByList(def.order_by.get());
488	            fuzzWindowFrame(def);
489	        }
490	
491	        fuzz(fn->children);
492	    }
493	    else if (auto * select = typeid_cast<ASTSelectQuery *>(ast.get()))
494	    {
495	        fuzzColumnLikeExpressionList(select->select().get());
496	        fuzzColumnLikeExpressionList(select->groupBy().get());
497	        fuzzOrderByList(select->orderBy().get());
498	
499	        fuzz(select->children);
500	    }
501	    /*
502	     * The time to fuzz the settings has not yet come.
503	     * Apparently we don't have any infractructure to validate the values of
504	     * the settings, and the first query with max_block_size = -1 breaks
505	     * because of overflows here and there.
506	     *//*
507	     * else if (auto * set = typeid_cast<ASTSetQuery *>(ast.get()))
508	     * {
509	     *      for (auto & c : set->changes)
510	     *      {
511	     *          if (fuzz_rand() % 50 == 0)
512	     *          {
513	     *              c.value = fuzzField(c.value);
514	     *          }
515	     *      }
516	     * }
517	     */
518	    else if (auto * literal = typeid_cast<ASTLiteral *>(ast.get()))
519	    {
520	        // There is a caveat with fuzzing the children: many ASTs also keep the
521	        // links to particular children in own fields. This means that replacing
522	        // the child with another object might lead to error. Many of these fields
523	        // are ASTPtr -- this is redundant ownership, but hides the error if the
524	        // child field is replaced. Others can be ASTLiteral * or the like, which
525	        // leads to segfault if the pointed-to AST is replaced.
526	        // Replacing children is safe in case of ASTExpressionList. In a more
527	        // general case, we can change the value of ASTLiteral, which is what we
528	        // do here.
529	        if (fuzz_rand() % 11 == 0)
530	        {
531	            literal->value = fuzzField(literal->value);
532	        }
533	    }
534	    else
535	    {
536	        fuzz(ast->children);
537	    }
538	}
